vulnerable_code:
fastify.get('/support/tickets/:ticketId/internal-audit', {
  schema: {
    params: {
      type: 'object',
      required: ['ticketId'],
      properties: {
        ticketId: { type: 'string', pattern: '^tkt-[0-9]{6,8}$' }
      }
    },
    querystring: {
      type: 'object',
      properties: {
        limit: { type: 'integer', default: 50 }
      }
    }
  },
  onRequest: [fastify.authenticate]
}, async (req, reply) => {
  const { ticketId } = req.params;
  const { limit } = req.query;

  const logs = await auditDb.collection('ticket_audit_events')
    .find({ ticketIdentifier: ticketId })
    .sort({ createdAt: -1 })
    .limit(limit)
    .toArray();

  if (!logs.length) return reply.status(404).send({ message: 'No logs found' });
  return reply.send({ ticketId, count: logs.length, events: logs });
});

corrected_code:
fastify.get('/support/tickets/:ticketId/internal-audit', {
  schema: {
    params: {
      type: 'object',
      required: ['ticketId'],
      properties: {
        ticketId: { type: 'string', pattern: '^tkt-[0-9]{6,8}$' }
      }
    },
    querystring: {
      type: 'object',
      properties: {
        limit: { type: 'integer', default: 50 }
      }
    }
  },
  onRequest: [fastify.authenticate]
}, async (req, reply) => {
  const { ticketId } = req.params;
  const { limit } = req.query;

  const ticket = await auditDb.collection('tickets').findOne({
    ticketIdentifier: ticketId,
    customerId: req.user.customerId
  });
  if (!ticket) return reply.status(403).send({ message: 'Access denied to target ticket audit logs' });

  const logs = await auditDb.collection('ticket_audit_events')
    .find({ ticketIdentifier: ticketId })
    .sort({ createdAt: -1 })
    .limit(limit)
    .toArray();

  return reply.send({ ticketId, count: logs.length, events: logs });
});
